//! Retry configuration.

/// Configuration for the bounded exponential retry policy.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for every retry delay, in milliseconds. Exponential
    /// delay growth saturates at this value.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry policy with the given attempt budget and delay
    /// bounds.
    pub fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Delay, in milliseconds, before the retry that follows
    /// `retry_index` failed attempts (`0` is the first retry).
    ///
    /// The delay is `min(base_delay_ms * 2^retry_index, max_delay_ms)`,
    /// so it doubles with every retry and saturates at `max_delay_ms`.
    /// Saturation arithmetic is used, so the result is well-defined for
    /// arbitrarily large retry counts: once `base_delay_ms * 2^n` would
    /// overflow `u64`, the delay is simply `max_delay_ms`.
    pub fn delay_for_retry(&self, retry_index: u32) -> u64 {
        let max = self.max_delay_ms;
        let base = self.base_delay_ms.min(max);
        if base == 0 {
            return 0;
        }
        // Largest shift amount that does not overflow `u64`. Shifting
        // `base` left by more than this would overflow, which can only
        // happen once the unbounded product already exceeds `max`.
        let max_shift = base.leading_zeros();
        if retry_index as u64 > max_shift as u64 {
            max
        } else {
            (base << retry_index).min(max)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn delay_grows_exponentially_from_base() {
        let config = RetryConfig::new(10, 10, 1000);
        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(1), 20);
        assert_eq!(config.delay_for_retry(2), 40);
        assert_eq!(config.delay_for_retry(3), 80);
        assert_eq!(config.delay_for_retry(4), 160);
    }

    #[test]
    fn delay_saturates_at_max_delay_ms() {
        let config = RetryConfig::new(10, 10, 100);
        assert_eq!(config.delay_for_retry(3), 80);
        assert_eq!(config.delay_for_retry(4), 100);
        assert_eq!(config.delay_for_retry(100), 100);
        assert_eq!(config.delay_for_retry(u32::MAX), 100);
    }

    #[test]
    fn base_above_max_is_capped_immediately() {
        let config = RetryConfig::new(3, 500, 100);
        assert_eq!(config.delay_for_retry(0), 100);
        assert_eq!(config.delay_for_retry(1), 100);
    }

    #[test]
    fn zero_max_delay_never_sleeps() {
        let config = RetryConfig::new(5, 10, 0);
        assert_eq!(config.delay_for_retry(0), 0);
        assert_eq!(config.delay_for_retry(1000), 0);
    }

    #[test]
    fn huge_retry_counts_saturate_without_overflow() {
        // 2^63 * 2 overflows u64; the policy must saturate instead.
        let config = RetryConfig::new(u32::MAX, 1u64 << 63, u64::MAX);
        assert_eq!(config.delay_for_retry(0), 1u64 << 63);
        assert_eq!(config.delay_for_retry(1), u64::MAX);
        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);

        // Even a maximal base never overflows.
        let config = RetryConfig::new(u32::MAX, u64::MAX, u64::MAX);
        assert_eq!(config.delay_for_retry(0), u64::MAX);
        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` when this error is a transient fault that may be
    /// retried. Permanent faults are never retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_classified_as_transient() {
        assert!(RetryError::Transient("network blip".to_string()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_transient() {
        assert!(!RetryError::Permanent("bad input".to_string()).is_transient());
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fake_sleeper_records_delays() {
        let mut sleeper = FakeSleeper::default();
        sleeper.sleep_ms(10);
        sleeper.sleep_ms(20);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
///
/// The policy is a bounded exponential backoff:
/// - Only `RetryError::Transient` errors are retried; permanent errors
///   return immediately.
/// - `max_attempts` includes the first call, so at most
///   `max_attempts - 1` retries happen.
/// - The delay before retry `n` (0-based) is
///   `min(base_delay_ms * 2^n, max_delay_ms)`: it doubles with every
///   retry and saturates at `max_delay_ms` without ever overflowing.
///
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut retry_index: u32 = 0;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) => {
                // Permanent faults never get retried, and the first call
                // already counts against `max_attempts`.
                if !err.is_transient() || retry_index + 1 >= config.max_attempts {
                    return Err(err);
                }
                sleeper.sleep_ms(config.delay_for_retry(retry_index));
                retry_index += 1;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn always_transient(msg: &str) -> impl FnMut() -> Result<(), RetryError> + '_ {
        let msg = msg.to_string();
        move || Err(RetryError::Transient(msg.clone()))
    }

    #[test]
    fn succeeds_on_first_attempt_without_sleeping() {
        let config = RetryConfig::new(3, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, || Ok(()));
        assert_eq!(result, Ok(()));
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let config = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut failures_left = 2;
        let result = run_job(&config, &mut sleeper, || {
            if failures_left > 0 {
                failures_left -= 1;
                Err(RetryError::Transient("not yet".to_string()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn retries_transient_errors_up_to_max_attempts() {
        let config = RetryConfig::new(4, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, always_transient("boom"));
        assert_eq!(result, Err(RetryError::Transient("boom".to_string())));
        // Three retries after the first call; delays double each time.
        assert_eq!(sleeper.sleeps, vec![10, 20, 40]);
    }

    #[test]
    fn max_attempts_one_never_retries() {
        let config = RetryConfig::new(1, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, always_transient("boom"));
        assert_eq!(result, Err(RetryError::Transient("boom".to_string())));
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_errors_return_immediately() {
        let config = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, || {
            Err(RetryError::Permanent("bad input".to_string()))
        });
        assert_eq!(result, Err(RetryError::Permanent("bad input".to_string())));
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_after_retries_returns_immediately() {
        let config = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls == 1 {
                Err(RetryError::Transient("flaky".to_string()))
            } else {
                Err(RetryError::Permanent("bad input".to_string()))
            }
        });
        assert_eq!(result, Err(RetryError::Permanent("bad input".to_string())));
        assert_eq!(sleeper.sleeps, vec![10]);
    }

    #[test]
    fn delays_saturate_at_max_delay_ms() {
        let config = RetryConfig::new(6, 10, 40);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, always_transient("boom"));
        assert_eq!(result, Err(RetryError::Transient("boom".to_string())));
        assert_eq!(sleeper.sleeps, vec![10, 20, 40, 40, 40]);
    }

    #[test]
    fn high_attempt_counts_do_not_overflow() {
        // A base of 2^63 would overflow when doubled; the policy must
        // saturate at max_delay_ms instead of panicking.
        let config = RetryConfig::new(70, 1u64 << 63, u64::MAX);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, always_transient("boom"));
        assert_eq!(result, Err(RetryError::Transient("boom".to_string())));
        assert_eq!(sleeper.sleeps.len(), 69);
        assert_eq!(sleeper.sleeps[0], 1u64 << 63);
        assert!(sleeper.sleeps[1..].iter().all(|&d| d == u64::MAX));
    }
}

//! Integration tests for the public retry policy API.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError, Sleeper};

/// A job that always fails with the given transient error.
fn always_transient(msg: &str) -> impl FnMut() -> Result<(), RetryError> + '_ {
    let msg = msg.to_string();
    move || Err(RetryError::Transient(msg.clone()))
}

#[test]
fn retries_transient_errors_with_exponential_backoff() {
    let config = RetryConfig::new(5, 100, 2000);
    let mut sleeper = FakeSleeper::default();
    let mut failures = 0;
    let result = run_job(&config, &mut sleeper, || {
        failures += 1;
        if failures < 4 {
            Err(RetryError::Transient("not ready".to_string()))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(failures, 4);
    // Delays double: 100, 200, 400.
    assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
}

#[test]
fn permanent_errors_return_immediately_without_retries() {
    let config = RetryConfig::new(10, 100, 2000);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Permanent("invalid request".to_string()))
    });
    assert_eq!(result, Err(RetryError::Permanent("invalid request".to_string())));
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_the_first_call() {
    let config = RetryConfig::new(3, 10, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("boom".to_string()))
    });
    assert_eq!(result, Err(RetryError::Transient("boom".to_string())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps.len(), 2);
}

#[test]
fn delay_growth_saturates_at_max_delay_ms() {
    // 2^7 = 128 already exceeds max_delay_ms, so every delay from the
    // 7th retry on is capped at 128.
    let config = RetryConfig::new(12, 1, 128);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, always_transient("boom"));
    assert_eq!(result, Err(RetryError::Transient("boom".to_string())));
    assert_eq!(sleeper.sleeps, vec![1, 2, 4, 8, 16, 32, 64, 128, 128, 128, 128]);
}

#[test]
fn huge_base_delay_saturates_without_overflow() {
    // Doubling 2^63 overflows u64; the policy must saturate at
    // max_delay_ms instead of panicking, for any number of attempts.
    let config = RetryConfig::new(10, 1u64 << 63, u64::MAX);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, always_transient("boom"));
    assert_eq!(result, Err(RetryError::Transient("boom".to_string())));
    assert_eq!(sleeper.sleeps[0], 1u64 << 63);
    assert!(sleeper.sleeps[1..].iter().all(|&d| d == u64::MAX));
}

#[test]
fn retry_delays_are_exposed_by_the_config() {
    let config = RetryConfig::new(1000, 5, 100);
    assert_eq!(config.delay_for_retry(0), 5);
    assert_eq!(config.delay_for_retry(1), 10);
    assert_eq!(config.delay_for_retry(4), 80);
    assert_eq!(config.delay_for_retry(5), 100);
    // Far beyond the safe exponent: saturated, never overflowing.
    assert_eq!(config.delay_for_retry(u32::MAX), 100);
}

