    32 |     /// arbitrarily large retry counts: once `base_delay_ms * 2^n` would
    33 |     /// overflow `u64`, the delay is simply `max_delay_ms`.
    34 |     pub fn delay_for_retry(&self, retry_index: u32) -> u64 {
