    42 |         // happen once the unbounded product already exceeds `max`.
    43 |         let max_shift = base.leading_zeros();
    44 |         if retry_index as u64 > max_shift as u64 {
    45 |             max
    46 |         } else {
    47 |             (base << retry_index).min(max)
    48 |         }
    49 |     }
